import unittest

from alpha.greeting import greeting


class GreetingTest(unittest.TestCase):
    def test_default(self):
        self.assertEqual(greeting(), "hello, demo")

    def test_name_at_limit_ok(self):
        greeting("a" * 64)

    def test_name_over_limit_raises(self):
        with self.assertRaises(ValueError) as cm:
            greeting("a" * 65)
        self.assertIn("64", str(cm.exception))

    def test_limit_counts_code_points(self):
        # 64 astral code points (each 2 UTF-16 units) is still allowed
        greeting("\U0001F600" * 64)
        with self.assertRaises(ValueError):
            greeting("\U0001F600" * 65)


if __name__ == "__main__":
    unittest.main()

MAX_NAME_CODE_POINTS = 64


def greeting(name: str | None = None) -> str:
    """Return the greeting text; with no name, `hello, demo`."""
    if name is None:
        return "hello, demo"
    if len(name) > MAX_NAME_CODE_POINTS:
        raise ValueError(
            f"name longer than the {MAX_NAME_CODE_POINTS}-character limit"
        )
    return f"hello, {name}"
